const items = [];

for (const item of $input.all()) {
  const now = new Date();
  const istTime = new Date(now.getTime() + (5.5 * 60 * 60 * 1000));
  const currentHour = istTime.getHours();

  // quiet hours check
  const isQuietHour = currentHour >= 23 || currentHour < 7;

  items.push({
    json: {
      ...item.json,         // keep previous fields
      isQuietHour,          // add quiet hour flag
      currentHour,
      istTime: istTime.toISOString()
    }
  });
}

return items;

return $input.all().map(item => ({
  json: { 
    ...item.json, 
    __startTime: Date.now(), 
    originalUrl: item.json.url   // keep a copy
  }
}));

const results = [];
const nowUtc = new Date();
const nowIst = new Date(nowUtc.getTime() + 5.5 * 60 * 60 * 1000);

// Original URLs
const prepareUrls = $('Prepare URLs1').all();
// Start times from Add Start Time node
const startTimes = $('Add Start Time').all();

for (const [i, item] of $input.all().entries()) {
  let httpCode = null;
  let status = 'Down';
  let error = '';
  let finalUrl = prepareUrls[i].json.url; // default = original url

  // Calculate response_ms using Add Start Time
  let responseMs = startTimes[i]?.json?.__startTime
    ? Date.now() - startTimes[i].json.__startTime
    : null;

  // Convert to seconds (human readable)
  let responseSec = responseMs !== null ? (responseMs / 1000).toFixed(2) + "s" : null;

  if (item.json.statusCode) {
    httpCode = item.json.statusCode;
    status = httpCode < 400 ? 'Up' : 'Down';

    // If 3xx → use redirected URL
    if (httpCode >= 300 && httpCode < 400 && item.json.url) {
      finalUrl = item.json.url;
    }
  } else if (item.json.error) {
    httpCode = item.json.error.status || item.json.error.code || null;
    error = item.json.error.message || item.json.error || 'Unknown Error';
    status = 'Down';
    finalUrl = "";   // blank if error
  }

  results.push({
    json: {
      url: prepareUrls[i].json.url,
      ts_utc: nowUtc.toISOString(),
      ts_ist: nowIst.toISOString(),
      status,
      response_ms: responseMs,
      response_s: responseSec,
      http_code: httpCode,
      error,
      final_url: finalUrl
    }
  });
}

return results;

// Calculate date range for last 7 days
const now = new Date();
// Convert to IST
const istNow = new Date(now.getTime() + (5.5 * 60 * 60 * 1000));

// Get 7 days ago
const sevenDaysAgo = new Date(istNow.getTime() - (7 * 24 * 60 * 60 * 1000));

// Format dates for filtering
const startDate = sevenDaysAgo.toISOString();
const endDate = istNow.toISOString();

return [{
  startDate: startDate,
  endDate: endDate,
  reportDate: istNow.toISOString().split('T')[0],
  istTime: istNow.toISOString()
}];

// Filter data for last 7 days and calculate metrics
const startDate = $node["Calculate Date Range"].json.startDate;
const endDate = $node["Calculate Date Range"].json.endDate;
const reportDate = $node["Calculate Date Range"].json.reportDate;

// Get all sheet data (skip header row)
const allData = $input.all().slice(1);

// Filter data for last 7 days
const last7DaysData = allData.filter(item => {
  const rowDate = new Date(item.json.ts_utc);  // ✅ Always use UTC for filtering
  return rowDate >= new Date(startDate) && rowDate <= new Date(endDate);
});



// Group data by URL
const urlGroups = {};
const urls = [
  "https://nytimes.com",
  "https://bbc.co.uk", 
  "https://cnn.com",
  "https://irctc.co.in",
  "https://wikipedia.org",
  "https://theguardian.com",
  "https://stackoverflow.com",
  "https://ndtv.com",
  "https://example.invalid",
  "https://no-such-host.invalid"
];

// Initialize groups
urls.forEach(url => {
  urlGroups[url] = {
    url: url,
    totalChecks: 0,
    upChecks: 0,
    downChecks: 0,
    totalResponseTime: 0,
    responseTimes: [],
    downtimeIncidents: 0,
    longestDowntime: 0,
    currentDowntimeStart: null,
    downtimes: []
  };
});

// Process each data point
last7DaysData.forEach(item => {
  const url = item.json.url;
  const status = item.json.status;
  const responseTime = parseInt(item.json.response_ms) || 0;
  const timestamp = new Date(item.json.ts_ist);

  if (urlGroups[url]) {
    urlGroups[url].totalChecks++;

    if (status === 'Up') {
      urlGroups[url].upChecks++;
      urlGroups[url].totalResponseTime += responseTime;
      urlGroups[url].responseTimes.push(responseTime);

      // End current downtime if exists
      if (urlGroups[url].currentDowntimeStart) {
        const downtimeDuration = timestamp - urlGroups[url].currentDowntimeStart;
        urlGroups[url].downtimes.push(downtimeDuration);
        urlGroups[url].currentDowntimeStart = null;
      }
    } else {
      urlGroups[url].downChecks++;

      // Start new downtime if not already started
      if (!urlGroups[url].currentDowntimeStart) {
        urlGroups[url].currentDowntimeStart = timestamp;
        urlGroups[url].downtimeIncidents++;
      }
    }
  }
});

// Calculate final metrics
const metrics = [];
const csvData = [];

Object.values(urlGroups).forEach(group => {
  const uptimePercentage = group.totalChecks > 0 ? 
    ((group.upChecks / group.totalChecks) * 100).toFixed(2) : '0.00';

  const avgResponseTime = group.responseTimes.length > 0 ? 
    Math.round(group.totalResponseTime / group.responseTimes.length) : 0;

  // Calculate longest downtime
  let longestDowntimeMs = 0;
  if (group.downtimes.length > 0) {
    longestDowntimeMs = Math.max(...group.downtimes);
  }

  // If currently down, calculate current downtime
  if (group.currentDowntimeStart) {
    const currentDowntime = new Date() - group.currentDowntimeStart;
    longestDowntimeMs = Math.max(longestDowntimeMs, currentDowntime);
  }

  const longestDowntimeMinutes = Math.round(longestDowntimeMs / (1000 * 60));

  metrics.push({
    url: group.url,
    uptimePercentage: uptimePercentage,
    avgResponseTime: avgResponseTime,
    downtimeIncidents: group.downtimeIncidents,
    longestDowntimeMinutes: longestDowntimeMinutes,
    totalChecks: group.totalChecks,
    upChecks: group.upChecks,
    downChecks: group.downChecks
  });
});

// Prepare CSV data (copy of filtered raw data)
last7DaysData.forEach(item => {
  csvData.push({
    url: item.json.url,
    ts_utc: item.json.ts_utc,
    ts_ist: item.json.ts_ist,
    status: item.json.status,
    response_ms: item.json.response_ms,
    http_code: item.json.http_code,
    error: item.json.error || '',
    final_url: item.json.final_url
  });
});

return [{
  metrics: metrics,
  csvData: csvData,
  reportDate: reportDate,
  startDate: startDate,
  endDate: endDate,
  totalDataPoints: last7DaysData.length
}];

// Generate CSV content for attachment
const csvData = $json.csvData;

// CSV Headers
const headers = ['url', 'ts_utc', 'ts_ist', 'status', 'response_ms', 'http_code', 'error', 'final_url'];

// Convert to CSV format
let csvContent = headers.join(',') + '\n';

csvData.forEach(row => {
  const csvRow = [
    `"${row.url}"`,
    `"${row.ts_utc}"`,
    `"${row.ts_ist}"`,
    `"${row.status}"`,
    row.response_ms,
    row.http_code,
    `"${row.error}"`,
    `"${row.final_url}"`
  ].join(',');

  csvContent += csvRow + '\n';
});

return [{
  ...($json),
  csvContent: csvContent,
  csvFileName: `uptime_report_${$json.reportDate}.csv`
}];

// Generate HTML email report
const metrics = $json.metrics;
const reportDate = $json.reportDate;
const totalDataPoints = $json.totalDataPoints;

// Calculate overall stats
let totalUptime = 0;
let totalIncidents = 0;
let totalChecks = 0;
let totalUp = 0;

metrics.forEach(m => {
  totalChecks += m.totalChecks;
  totalUp += m.upChecks;
  totalIncidents += m.downtimeIncidents;
});

const overallUptime = totalChecks > 0 ? ((totalUp / totalChecks) * 100).toFixed(2) : '0.00';

// Generate table rows
let tableRows = '';
metrics.forEach(metric => {
  const statusIcon = parseFloat(metric.uptimePercentage) >= 99 ? '🟢' : 
                    parseFloat(metric.uptimePercentage) >= 95 ? '🟡' : '🔴';

  tableRows += `
  <tr>
    <td style="padding: 8px; border: 1px solid #ddd;">${statusIcon} ${metric.url}</td>
    <td style="padding: 8px; border: 1px solid #ddd; text-align: center;">${metric.uptimePercentage}%</td>
    <td style="padding: 8px; border: 1px solid #ddd; text-align: center;">${metric.avgResponseTime}ms</td>
    <td style="padding: 8px; border: 1px solid #ddd; text-align: center;">${metric.downtimeIncidents}</td>
    <td style="padding: 8px; border: 1px solid #ddd; text-align: center;">${metric.longestDowntimeMinutes}min</td>
    <td style="padding: 8px; border: 1px solid #ddd; text-align: center;">${metric.totalChecks}</td>
  </tr>`;
});

const emailContent = `
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    .header { background: #f4f4f4; padding: 20px; border-radius: 5px; margin-bottom: 20px; }
    .summary { background: #e8f5e8; padding: 15px; border-radius: 5px; margin-bottom: 20px; }
    table { width: 100%; border-collapse: collapse; margin: 20px 0; }
    th { background: #4CAF50; color: white; padding: 10px; border: 1px solid #ddd; }
    .footer { margin-top: 30px; font-size: 12px; color: #666; }
  </style>
</head>
<body>
  <div class="header">
    <h1>📊 Website Uptime Weekly Report</h1>
    <p><strong>Report Date:</strong> ${reportDate}</p>
    <p><strong>Monitoring Period:</strong> Last 7 Days</p>
  </div>

  <div class="summary">
    <h2>📈 Overall Summary</h2>
    <ul>
      <li><strong>Overall Uptime:</strong> ${overallUptime}%</li>
      <li><strong>Total Incidents:</strong> ${totalIncidents}</li>
      <li><strong>Total Checks:</strong> ${totalChecks}</li>
      <li><strong>Data Points:</strong> ${totalDataPoints}</li>
    </ul>
  </div>

  <h2>🌐 Website Performance Details</h2>
  <table>
    <tr>
      <th>Website</th>
      <th>Uptime %</th>
      <th>Avg Response Time</th>
      <th>Downtime Incidents</th>
      <th>Longest Downtime</th>
      <th>Total Checks</th>
    </tr>
    ${tableRows}
  </table>

  <div class="footer">
    <hr>
    <p>🟢 Excellent (≥99%) | 🟡 Good (≥95%) | 🔴 Needs Attention (<95%)</p>
    <p><strong>Note:</strong> Raw monitoring data is attached as CSV file for detailed analysis.</p>
    <p><small>This report was automatically generated by your Website Uptime Monitor on ${new Date().toLocaleString('en-IN', {timeZone: 'Asia/Kolkata'})} IST</small></p>
  </div>
</body>
</html>
`;

return [{
  ...($json),
  emailContent: emailContent,
  emailSubject: `📊 Weekly Uptime Report - ${reportDate} (Overall: ${overallUptime}%)`
}];
